// ============================================================================
// CAN_XL_apb: APB4 register wrapper around CAN_XL_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CAN_XL.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CAN_XL.md
// ============================================================================
module CAN_XL_apb #(
  parameter int MAX_BYTES = 64,
  parameter int FS = 10,
  localparam int BW = $clog2(MAX_BYTES),
  localparam int WW = BW - 2
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxd,
  output logic txd,
  output logic tx_fast,
  output logic rx_fast
);
  localparam logic [31:0] ID_VALUE = 32'h584C0100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [32:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd33) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22] | hit[23] | hit[24] | hit[25] | hit[26] | hit[27] | hit[28])));   // core registers take whole words

  // ---------------- core ----------------
  logic [5:0]    c_cfg_brp;
  logic [3:0]    c_cfg_tseg1;
  logic [2:0]    c_cfg_tseg2;
  logic [1:0]    c_cfg_sjw;
  logic [5:0]    c_cfg_dbrp;
  logic [3:0]    c_cfg_dtseg1;
  logic [2:0]    c_cfg_dtseg2;
  logic [1:0]    c_cfg_dsjw;
  logic [28:0]   c_acc_code;
  logic [28:0]   c_acc_mask;
  logic          c_hb_wen;
  logic [31:0]   c_hb_wdata;
  logic [31:0]   c_hb_rdata;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic          c_tx_xl;
  logic [28:0]   c_tx_id;
  logic          c_tx_ide;
  logic          c_tx_rtr;
  logic [10:0]   c_tx_dlc;
  logic [7:0]    c_tx_sdt;
  logic          c_tx_sec;
  logic [7:0]    c_tx_vcid;
  logic [31:0]   c_tx_af;
  logic          c_tx_abort;
  logic          c_tx_done;
  logic          c_tx_aborted;
  logic          c_tx_rejected;
  logic          c_rx_valid;
  logic          c_rx_xl;
  logic [28:0]   c_rx_id;
  logic          c_rx_ide;
  logic          c_rx_rtr;
  logic [10:0]   c_rx_dlc;
  logic [7:0]    c_rx_sdt;
  logic          c_rx_sec;
  logic [7:0]    c_rx_vcid;
  logic [31:0]   c_rx_af;
  logic          c_rx_trunc;
  logic          c_arb_lost;
  logic          c_err_bit;
  logic          c_err_stuff;
  logic          c_err_crc;
  logic          c_err_form;
  logic          c_err_ack;
  logic          c_pexc;
  logic [8:0]    c_tec;
  logic [7:0]    c_rec;
  logic          c_err_passive;
  logic          c_bus_off;
  CAN_XL_top #(.MAX_BYTES(MAX_BYTES), .FS(FS)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxd(rxd),
    .txd(txd),
    .tx_fast(tx_fast),
    .rx_fast(rx_fast),
    .cfg_brp(c_cfg_brp),
    .cfg_tseg1(c_cfg_tseg1),
    .cfg_tseg2(c_cfg_tseg2),
    .cfg_sjw(c_cfg_sjw),
    .cfg_dbrp(c_cfg_dbrp),
    .cfg_dtseg1(c_cfg_dtseg1),
    .cfg_dtseg2(c_cfg_dtseg2),
    .cfg_dsjw(c_cfg_dsjw),
    .acc_code(c_acc_code),
    .acc_mask(c_acc_mask),
    .hb_wen(c_hb_wen),
    .hb_waddr((wr ? ((hit[13] ? 4'd0 : 4'd0) | (hit[14] ? 4'd1 : 4'd0) | (hit[15] ? 4'd2 : 4'd0) | (hit[16] ? 4'd3 : 4'd0) | (hit[17] ? 4'd4 : 4'd0) | (hit[18] ? 4'd5 : 4'd0) | (hit[19] ? 4'd6 : 4'd0) | (hit[20] ? 4'd7 : 4'd0) | (hit[21] ? 4'd8 : 4'd0) | (hit[22] ? 4'd9 : 4'd0) | (hit[23] ? 4'd10 : 4'd0) | (hit[24] ? 4'd11 : 4'd0) | (hit[25] ? 4'd12 : 4'd0) | (hit[26] ? 4'd13 : 4'd0) | (hit[27] ? 4'd14 : 4'd0) | (hit[28] ? 4'd15 : 4'd0)) : 4'd0)),
    .hb_wdata(c_hb_wdata),
    .hb_raddr((rd ? ((hit[13] ? 4'd0 : 4'd0) | (hit[14] ? 4'd1 : 4'd0) | (hit[15] ? 4'd2 : 4'd0) | (hit[16] ? 4'd3 : 4'd0) | (hit[17] ? 4'd4 : 4'd0) | (hit[18] ? 4'd5 : 4'd0) | (hit[19] ? 4'd6 : 4'd0) | (hit[20] ? 4'd7 : 4'd0) | (hit[21] ? 4'd8 : 4'd0) | (hit[22] ? 4'd9 : 4'd0) | (hit[23] ? 4'd10 : 4'd0) | (hit[24] ? 4'd11 : 4'd0) | (hit[25] ? 4'd12 : 4'd0) | (hit[26] ? 4'd13 : 4'd0) | (hit[27] ? 4'd14 : 4'd0) | (hit[28] ? 4'd15 : 4'd0)) : 4'd0)),
    .hb_rdata(c_hb_rdata),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_xl(c_tx_xl),
    .tx_id(c_tx_id),
    .tx_ide(c_tx_ide),
    .tx_rtr(c_tx_rtr),
    .tx_dlc(c_tx_dlc),
    .tx_sdt(c_tx_sdt),
    .tx_sec(c_tx_sec),
    .tx_vcid(c_tx_vcid),
    .tx_af(c_tx_af),
    .tx_abort(c_tx_abort),
    .tx_done(c_tx_done),
    .tx_aborted(c_tx_aborted),
    .tx_rejected(c_tx_rejected),
    .rx_valid(c_rx_valid),
    .rx_xl(c_rx_xl),
    .rx_id(c_rx_id),
    .rx_ide(c_rx_ide),
    .rx_rtr(c_rx_rtr),
    .rx_dlc(c_rx_dlc),
    .rx_sdt(c_rx_sdt),
    .rx_sec(c_rx_sec),
    .rx_vcid(c_rx_vcid),
    .rx_af(c_rx_af),
    .rx_trunc(c_rx_trunc),
    .arb_lost(c_arb_lost),
    .err_bit(c_err_bit),
    .err_stuff(c_err_stuff),
    .err_crc(c_err_crc),
    .err_form(c_err_form),
    .err_ack(c_err_ack),
    .pexc(c_pexc),
    .tec(c_tec),
    .rec(c_rec),
    .err_passive(c_err_passive),
    .bus_off(c_bus_off)
  );

  // ---------------- registers ----------------
  logic [12:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [14:0] r_NBTR;   // 12'h014 NBTR
  logic [14:0] r_DBTR;   // 12'h018 DBTR
  logic [28:0] r_ACC_CODE;   // 12'h01C ACC_CODE
  logic [28:0] r_ACC_MASK;   // 12'h020 ACC_MASK
  logic [31:0] r_TX_ID;   // 12'h024 TX_ID
  logic [27:0] r_TX_CTRL;   // 12'h028 TX_CTRL
  logic [31:0] r_TX_AF;   // 12'h02C TX_AF
  logic [1:0] p_CMD;   // 12'h030 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_NBTR <= 15'h2941;
      r_DBTR <= 15'h4C0;
      r_ACC_CODE <= 29'h0;
      r_ACC_MASK <= 29'h0;
      r_TX_ID <= 32'h0;
      r_TX_CTRL <= 28'h0;
      r_TX_AF <= 32'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[12:0] & wmask[12:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_NBTR <= (r_NBTR & ~wmask[14:0]) | (PWDATA[14:0] & wmask[14:0]);
      if (wr && hit[6]) r_DBTR <= (r_DBTR & ~wmask[14:0]) | (PWDATA[14:0] & wmask[14:0]);
      if (wr && hit[7]) r_ACC_CODE <= (r_ACC_CODE & ~wmask[28:0]) | (PWDATA[28:0] & wmask[28:0]);
      if (wr && hit[8]) r_ACC_MASK <= (r_ACC_MASK & ~wmask[28:0]) | (PWDATA[28:0] & wmask[28:0]);
      if (wr && hit[9]) r_TX_ID <= (r_TX_ID & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_TX_CTRL <= (r_TX_CTRL & ~wmask[27:0]) | (PWDATA[27:0] & wmask[27:0]);
      if (wr && hit[11]) r_TX_AF <= (r_TX_AF & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[12]) ? PWDATA[1:0] & wmask[1:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_brp = r_NBTR[5:0];
  assign c_cfg_tseg1 = r_NBTR[9:6];
  assign c_cfg_tseg2 = r_NBTR[12:10];
  assign c_cfg_sjw = r_NBTR[14:13];
  assign c_cfg_dbrp = r_DBTR[5:0];
  assign c_cfg_dtseg1 = r_DBTR[9:6];
  assign c_cfg_dtseg2 = r_DBTR[12:10];
  assign c_cfg_dsjw = r_DBTR[14:13];
  assign c_acc_code = r_ACC_CODE[28:0];
  assign c_acc_mask = r_ACC_MASK[28:0];
  assign c_tx_id = r_TX_ID[28:0];
  assign c_tx_ide = r_TX_ID[29:29];
  assign c_tx_rtr = r_TX_ID[30:30];
  assign c_tx_xl = r_TX_ID[31:31];
  assign c_tx_dlc = r_TX_CTRL[10:0];
  assign c_tx_sdt = r_TX_CTRL[18:11];
  assign c_tx_sec = r_TX_CTRL[19:19];
  assign c_tx_vcid = r_TX_CTRL[27:20];
  assign c_tx_af = r_TX_AF[31:0];
  assign c_tx_valid = p_CMD[0:0];
  assign c_tx_abort = p_CMD[1:1];
  // BUF: the core's register port (indices on the instance)
  assign c_hb_wen = wr & (PSTRB == 4'hF) & (hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22] | hit[23] | hit[24] | hit[25] | hit[26] | hit[27] | hit[28]);
  assign c_hb_wdata = PWDATA[31:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_tx_aborted;
    irq_set[2] = c_tx_rejected;
    irq_set[3] = c_rx_valid;
    irq_set[4] = c_arb_lost;
    irq_set[5] = c_err_bit;
    irq_set[6] = c_err_stuff;
    irq_set[7] = c_err_crc;
    irq_set[8] = c_err_form;
    irq_set[9] = c_err_ack;
    irq_set[10] = c_pexc;
    irq_set[11] = c_err_passive;
    irq_set[12] = c_bus_off;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_NBTR);
      10'd6: apb_rdata = 32'(r_DBTR);
      10'd7: apb_rdata = 32'(r_ACC_CODE);
      10'd8: apb_rdata = 32'(r_ACC_MASK);
      10'd9: apb_rdata = 32'(r_TX_ID);
      10'd10: apb_rdata = 32'(r_TX_CTRL);
      10'd11: apb_rdata = 32'(r_TX_AF);
      10'd13: apb_rdata = 32'(c_hb_rdata);
      10'd14: apb_rdata = 32'(c_hb_rdata);
      10'd15: apb_rdata = 32'(c_hb_rdata);
      10'd16: apb_rdata = 32'(c_hb_rdata);
      10'd17: apb_rdata = 32'(c_hb_rdata);
      10'd18: apb_rdata = 32'(c_hb_rdata);
      10'd19: apb_rdata = 32'(c_hb_rdata);
      10'd20: apb_rdata = 32'(c_hb_rdata);
      10'd21: apb_rdata = 32'(c_hb_rdata);
      10'd22: apb_rdata = 32'(c_hb_rdata);
      10'd23: apb_rdata = 32'(c_hb_rdata);
      10'd24: apb_rdata = 32'(c_hb_rdata);
      10'd25: apb_rdata = 32'(c_hb_rdata);
      10'd26: apb_rdata = 32'(c_hb_rdata);
      10'd27: apb_rdata = 32'(c_hb_rdata);
      10'd28: apb_rdata = 32'(c_hb_rdata);
      10'd29: apb_rdata = 32'({c_rx_xl, c_rx_rtr, c_rx_ide, c_rx_id});
      10'd30: apb_rdata = 32'({c_rx_trunc, c_rx_vcid, c_rx_sec, c_rx_sdt, c_rx_dlc});
      10'd31: apb_rdata = 32'({c_rx_af});
      10'd32: apb_rdata = 32'({c_bus_off, c_err_passive, c_rec, c_tec, c_tx_ready});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
